public class Main {
    static int kthLargest(int[] nums, int k) {
        int target = nums.length - k;
        int left = 0, right = nums.length - 1;
        Random random = new Random(42);
        while (left <= right) {
            int pivotIndex = left + random.nextInt(right - left + 1);
            pivotIndex = partition(nums, left, right, pivotIndex);
            if (pivotIndex == target) return nums[pivotIndex];
            if (pivotIndex < target) left = pivotIndex + 1;
            else right = pivotIndex - 1;
        }
        throw new IllegalArgumentException("Invalid k");
    }

    static int partition(int[] a, int left, int right, int pivotIndex) {
        int pivot = a[pivotIndex];
        int t=a[pivotIndex]; a[pivotIndex]=a[right]; a[right]=t;
        int store=left;
        for(int i=left;i<right;i++) if(a[i]<pivot){ t=a[i];a[i]=a[store];a[store]=t;store++; }
        t=a[store];a[store]=a[right];a[right]=t;
        return store;
    }

    public static void main(String[] args) {
        System.out.println(kthLargest(new int[]{3,2,1,5,6,4}, 2));
    }
}

