        Set<Integer> set = new HashSet<>();
        for (int n : nums) set.add(n);
        int best = 0;
        for (int n : set) {
            if (!set.contains(n - 1)) {
                int current = n;
                while (set.contains(current)) current++;
                best = Math.max(best, current - n);
            }
        }
        return best;
    }

