import java.util.concurrent.locks.*;

public class Main {
    static class BoundedQueue<T> {
        private final Object[] items;
        private int head, tail, count;
        private final Lock lock = new ReentrantLock();
        private final Condition notFull = lock.newCondition();
        private final Condition notEmpty = lock.newCondition();
        BoundedQueue(int capacity){ items=new Object[capacity]; }
        void put(T value) throws InterruptedException {
            lock.lock();
            try { while(count==items.length) notFull.await(); items[tail]=value; tail=(tail+1)%items.length; count++; notEmpty.signal(); }
            finally { lock.unlock(); }
        }
        @SuppressWarnings("unchecked") T take() throws InterruptedException {
            lock.lock();
            try { while(count==0) notEmpty.await(); T value=(T)items[head]; items[head]=null; head=(head+1)%items.length; count--; notFull.signal(); return value; }
            finally { lock.unlock(); }
        }
    }
    public static void main(String[] args) throws Exception {
        BoundedQueue<Integer> q=new BoundedQueue<>(2); q.put(10);q.put(20);System.out.println(q.take());System.out.println(q.take());
    }
}

