public class Main {
    static int countIslands(char[][] grid) {
        int count = 0;
        int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[0].length; c++) {
                if (grid[r][c] != '1') continue;
                count++;
                Queue<int[]> q = new ArrayDeque<>(); q.offer(new int[]{r,c}); grid[r][c] = '0';
                while (!q.isEmpty()) {
