            while (!a[i].startsWith(p)) {
                p = p.substring(0, p.length() - 1);
                if (p.isEmpty()) return "";
            }
        }
        return p;
    }
    public static void main(String[] args) {
        String[] input = {"flower", "flow", "flight"};
        System.out.println("Output: " + longestCommonPrefix(input));
    }
}

