public class Main {
    static class Node { int v; Node next; Node(int v){this.v=v;} }
    static Node merge(Node a, Node b) {
        Node dummy = new Node(0), cur = dummy;
        while (a != null && b != null) {
            if (a.v <= b.v) { cur.next = a; a = a.next; }
            else { cur.next = b; b = b.next; }
            cur = cur.next;
        }
        cur.next = a != null ? a : b;
        return dummy.next;
    }
    static void print(Node n){ while(n!=null){System.out.print(n.v + (n.next==null?"\\n":" -> ")); n=n.next;} }
    public static void main(String[] args) {
        Node a=new Node(1); a.next=new Node(2); a.next.next=new Node(4);
        Node b=new Node(1); b.next=new Node(3); b.next.next=new Node(4);
        print(merge(a,b));
    }
}

public class Main {
    static class Node { int v; Node next; Node(int v){this.v=v;} }
    static Node remove(Node head, int n) {
        Node dummy = new Node(0); dummy.next = head;
        Node fast = dummy, slow = dummy;
        for(int i=0;i<n;i++) fast=fast.next;
        while(fast.next!=null){fast=fast.next; slow=slow.next;}
        slow.next=slow.next.next;
        return dummy.next;
    }
    static void print(Node n){while(n!=null){System.out.print(n.v+(n.next==null?"\\n":" -> "));n=n.next;}}
    public static void main(String[] args){
        Node h=new Node(1); h.next=new Node(2); h.next.next=new Node(3); h.next.next.next=new Node(4); h.next.next.next.next=new Node(5);
        print(remove(h,2));
    }
}

