public class Main {
    static int eval(String[] tokens){
        Deque<Integer> s=new ArrayDeque<>();
        for(String t:tokens){
            if("+-*/".contains(t) && t.length()==1){int b=s.pop(),a=s.pop(); switch(t){case "+":s.push(a+b);break;case "-":s.push(a-b);break;case "*":s.push(a*b);break;default:s.push(a/b);}} else s.push(Integer.parseInt(t));
