import java.util.*;
public class Main {
    static int ladder(String begin,String end,List<String> words){
        Set<String> dict=new HashSet<>(words); if(!dict.contains(end))return 0;
        Queue<String> q=new ArrayDeque<>(); q.add(begin); int steps=1;
        while(!q.isEmpty()){for(int size=q.size();size>0;size--){String w=q.poll();if(w.equals(end))return steps;char[] a=w.toCharArray();for(int i=0;i<a.length;i++){char old=a[i];for(char c='a';c<='z';c++){if(c==old)continue;a[i]=c;String n=new String(a);if(dict.remove(n))q.add(n);}a[i]=old;}}steps++;}
        return 0;
    }
    public static void main(String[] args){System.out.println(ladder("hit","cog",Arrays.asList("hot","dot","dog","lot","log","cog")));}
}

