    static int lis(int[] a){
        int[] tails=new int[a.length]; int size=0;
        for(int x:a){int l=0,r=size;while(l<r){int m=(l+r)/2;if(tails[m]<x)l=m+1;else r=m;}tails[l]=x;if(l==size)size++;}
